package odk.malicompetences.backend.opportunite;
import odk.malicompetences.backend.territoire.Territoire; import odk.malicompetences.backend.utilisateur.Utilisateur; import org.springframework.stereotype.Component; import java.time.LocalDateTime; import java.util.UUID;
@Component public class OpportuniteMapper {
 public Opportunite toEntity(OpportuniteRequest r,CategorieOpportunite c,Territoire t,Utilisateur auteur){Opportunite o=new Opportunite();o.setCategorie(c);o.setTerritoire(t);o.setCreePar(auteur);o.setTitre(r.titre());o.setDescription(r.description());o.setOrganisme(r.organisme());o.setLienExterne(r.lienExterne());o.setContact(r.contact());o.setStatut(r.statut());o.setDateExpiration(r.dateExpiration());if(r.statut()==StatutOpportunite.PUBLIEE)o.setPublieeLe(LocalDateTime.now());return o;}
 public void updateEntity(OpportuniteRequest r,Opportunite o,CategorieOpportunite c,Territoire t){if(c!=null)o.setCategorie(c);o.setTerritoire(t);o.setTitre(r.titre());o.setDescription(r.description());o.setOrganisme(r.organisme());o.setLienExterne(r.lienExterne());o.setContact(r.contact());o.setDateExpiration(r.dateExpiration());if(r.statut()!=o.getStatut()){o.setStatut(r.statut());if(r.statut()==StatutOpportunite.PUBLIEE)o.setPublieeLe(LocalDateTime.now());}}
 public OpportuniteResponse toResponse(Opportunite o){return new OpportuniteResponse(o.getId(),o.getCategorie().getId(),o.getCategorie().getNom(),o.getTitre(),o.getDescription(),o.getOrganisme(),o.getLienExterne(),o.getContact(),o.getTerritoire()==null?null:o.getTerritoire().getId(),o.getStatut(),o.getPublieeLe(),o.getDateExpiration(),o.getCreePar().getId());}
}
